TODO_SOURCE = 'import argparse\nimport json\nfrom pathlib import Path\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(description="Small JSON TODO CLI")\n    parser.add_argument("--file", type=Path, default=Path("todos.json"))\n    sub = parser.add_subparsers(dest="command", required=True)\n    sub.add_parser("add").add_argument("text")\n    sub.add_parser("list")\n    sub.add_parser("delete").add_argument("id", type=int)\n    args = parser.parse_args(argv)\n    try:\n        data = json.loads(args.file.read_text(encoding="utf-8")) if args.file.exists() else {"next_id": 1, "tasks": []}\n        if args.command == "list":\n            for task in data["tasks"]:\n                print(f"{task[\'id\']}: {task[\'text\']}")\n            return\n        if args.command == "add":\n            if not args.text.strip():\n                parser.error("task text must not be empty")\n            data["tasks"].append({"id": data["next_id"], "text": args.text.strip()})\n            data["next_id"] += 1\n        else:\n            if not any(t["id"] == args.id for t in data["tasks"]):\n                parser.error("task ID not found")\n            data["tasks"] = [t for t in data["tasks"] if t["id"] != args.id]\n        temporary = args.file.with_suffix(args.file.suffix + ".tmp")\n        temporary.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")\n        temporary.replace(args.file)\n    except (OSError, ValueError, KeyError, TypeError) as exc:\n        parser.error(str(exc))\n\n\nif __name__ == "__main__":\n    main()\n'
TODO_TESTS = 'import subprocess\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\n\n\nclass TodoTests(unittest.TestCase):\n    def setUp(self):\n        self.temp = tempfile.TemporaryDirectory()\n        self.addCleanup(self.temp.cleanup)\n        self.db = Path(self.temp.name) / "tasks.json"\n\n    def run_cli(self, *args):\n        return subprocess.run([sys.executable, str(Path(__file__).with_name("todo.py")), "--file", str(self.db), *args], capture_output=True, text=True, timeout=10)\n\n    def test_lifecycle(self):\n        self.assertEqual(self.run_cli("add", "buy milk").returncode, 0)\n        self.assertIn("buy milk", self.run_cli("list").stdout)\n        self.assertEqual(self.run_cli("delete", "1").returncode, 0)\n        self.assertNotIn("buy milk", self.run_cli("list").stdout)\n\n    def test_invalid_input(self):\n        self.assertNotEqual(self.run_cli("add", "   ").returncode, 0)\n        self.assertNotEqual(self.run_cli("delete", "404").returncode, 0)\n\n    def test_stable_ids(self):\n        self.run_cli("add", "first")\n        self.run_cli("delete", "1")\n        self.run_cli("add", "second")\n        self.assertIn("2:", self.run_cli("list").stdout)\n\n    def test_empty_list(self):\n        result = self.run_cli("list")\n        self.assertEqual(result.returncode, 0)\n        self.assertEqual(result.stdout, "")\n\n\nif __name__ == "__main__":\n    unittest.main()\n'
USAGE = '# TODO CLI\npython todo.py --file todos.json add "buy milk"\npython todo.py --file todos.json list\npython todo.py --file todos.json delete 1\n\nEmpty task text and missing delete IDs return a nonzero exit code.\nRun tests: python -m unittest discover -v\n'
